CREATE TABLE selection_rounds(id BIGSERIAL PRIMARY KEY,drive_id BIGINT NOT NULL REFERENCES campus_drives(id),name VARCHAR(255) NOT NULL,round_type VARCHAR(50) NOT NULL,round_order INTEGER NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,location VARCHAR(255),results_published BOOLEAN NOT NULL DEFAULT FALSE,archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_round_drive_order UNIQUE(drive_id,round_order));
CREATE TABLE round_participants(id BIGSERIAL PRIMARY KEY,round_id BIGINT NOT NULL REFERENCES selection_rounds(id),application_id BIGINT NOT NULL REFERENCES job_applications(id),attendance_status VARCHAR(20) NOT NULL DEFAULT 'REGISTERED',created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_round_application UNIQUE(round_id,application_id));
CREATE TABLE round_results(id BIGSERIAL PRIMARY KEY,participant_id BIGINT NOT NULL UNIQUE REFERENCES round_participants(id),status VARCHAR(30) NOT NULL DEFAULT 'PENDING',score NUMERIC(8,2),notes VARCHAR(1000),published BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE offers(id BIGSERIAL PRIMARY KEY,institution_id BIGINT NOT NULL REFERENCES institutions(id),application_id BIGINT NOT NULL UNIQUE REFERENCES job_applications(id),student_id BIGINT NOT NULL REFERENCES students(id),company_id BIGINT NOT NULL REFERENCES companies(id),role_title VARCHAR(255) NOT NULL,package_amount NUMERIC(14,2) NOT NULL,currency VARCHAR(3) NOT NULL,letter_object_key VARCHAR(500),status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',verified BOOLEAN NOT NULL DEFAULT FALSE,response_deadline TIMESTAMPTZ,offered_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_offer_package CHECK(package_amount>=0));
CREATE INDEX idx_offer_student ON offers(student_id);CREATE INDEX idx_offer_status ON offers(status);CREATE INDEX idx_offer_institution ON offers(institution_id);
CREATE TABLE placement_outcomes(id BIGSERIAL PRIMARY KEY,offer_id BIGINT NOT NULL UNIQUE REFERENCES offers(id),student_id BIGINT NOT NULL REFERENCES students(id),company_id BIGINT NOT NULL REFERENCES companies(id),package_amount NUMERIC(14,2) NOT NULL,currency VARCHAR(3) NOT NULL,placed_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_outcome_student ON placement_outcomes(student_id);CREATE INDEX idx_outcome_company ON placement_outcomes(company_id);
CREATE TABLE notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),title VARCHAR(255) NOT NULL,message TEXT NOT NULL,type VARCHAR(50) NOT NULL,link_url VARCHAR(500),read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_notification_user_read ON notifications(user_id,read_at);
CREATE TABLE announcements(id BIGSERIAL PRIMARY KEY,institution_id BIGINT NOT NULL REFERENCES institutions(id),created_by BIGINT NOT NULL REFERENCES users(id),title VARCHAR(255) NOT NULL,content TEXT NOT NULL,audience_role VARCHAR(30),published_at TIMESTAMPTZ,expires_at TIMESTAMPTZ,archived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_announcement_institution_published ON announcements(institution_id,published_at DESC);
